import sys,os,re,glob,xml.etree.ElementTree as ET
NS='{http://www.collada.org/2005/11/COLLADASchema}'
def mm(a,b): return [[sum(a[i][k]*b[k][j] for k in range(4)) for j in range(4)] for i in range(4)]
def ap(M,v): return [sum(M[i][k]*v[k] for k in range(3))+M[i][3] for i in range(3)]
I=[[1 if i==j else 0 for j in range(4)] for i in range(4)]
def dae(path):
    r=ET.parse(path).getroot(); up=r.find(f'.//{NS}up_axis'); up=up.text if up is not None else 'Y_UP'
    unit=r.find(f'.//{NS}unit'); us=float(unit.get('meter')) if unit is not None else 1
    geoms={}
    for g in r.iter(NS+'geometry'):
        m=g.find(NS+'mesh')
        if m is None: continue
        fa=list(map(float,m.find(NS+'source').find(NS+'float_array').text.split()))
        geoms[g.get('id')]=[fa[i:i+3] for i in range(0,len(fa),3)]
    tags={};cmin=[];
    def walk(n,M):
        for ch in n.findall(NS+'node'):
            L=I
            for e in ch:
                t=e.tag[len(NS):]
                if t=='matrix':
                    v=list(map(float,e.text.split()));L=mm(L,[v[0:4],v[4:8],v[8:12],v[12:16]])
                elif t=='translate':
                    x,y,z=map(float,e.text.split());L=mm(L,[[1,0,0,x],[0,1,0,y],[0,0,1,z],[0,0,0,1]])
                elif t=='scale':
                    x,y,z=map(float,e.text.split());L=mm(L,[[x,0,0,0],[0,y,0,0],[0,0,z,0],[0,0,0,1]])
            W=mm(M,L);nm=ch.get('name') or ''
            tags[nm]=W
            ig=ch.find(NS+'instance_geometry')
            if ig is not None and ig.get('url')[1:] in geoms:
                yield nm,[ap(W,v) for v in geoms[ig.get('url')[1:]]]
            yield from walk(ch,W)
    out=[]
    for vs in r.iter(NS+'visual_scene'): out+=list(walk(vs,I))
    conv=(lambda p:(p[0],p[2],-p[1])) if up=='Z_UP' else (lambda p:tuple(p))
    return up,us,tags,[(n,[conv(p) for p in ps]) for n,ps in out],conv
def objv(path):
    return [tuple(map(float,l.split()[1:4])) for l in open(path) if l.startswith('v ')]
for d in sorted(glob.glob(sys.argv[1]+'/*/')):
  for mf in glob.glob(d+'*.model'):
    txt=open(mf).read()
    meshes=re.findall(r'^\s*mesh\s+(\S+)',txt,re.M); col=re.findall(r'^\s*collision\s+(\S+)',txt,re.M)
    tagy=None; cy=[]
    for f in meshes+col:
        p=d+f
        if not os.path.exists(p) or not p.endswith('.dae'): continue
        up,us,tags,geo,conv=dae(p)
        for n,W in tags.items():
            if n.startswith('tag_landing'): tagy=conv([W[0][3],W[1][3],W[2][3]])[1]
        for n,ps in geo:
            if n.startswith('collision') or f in col: cy+= [q[1] for q in ps]
    for f in col:
        if f.endswith('.obj'): cy+=[v[1] for v in objv(d+f)]
    print(f"{os.path.basename(mf):28s} tag_landing={tagy} colmin={min(cy) if cy else None:}")
